package dev.enginehost

import org.bouncycastle.asn1.x509.KeyUsage
import org.junit.Assert.assertEquals
import org.junit.Assert.assertFalse
import org.junit.Assert.assertTrue
import org.junit.Assert.fail
import org.junit.Test
import java.util.Date

/**
 * Signature format v1 (Droidtop/tracker#550): a JWS whose x5c chain is
 * verified up to the pinned Droidtop Core certificate and never past it.
 * Every certificate here is generated by this run ([TestPki]).
 */
class CertificateSignaturesTest {
    private val pki = TestPki.Hierarchy()
    private val manifest = """{"bundleId":"dev.enginehost.example"}""".toByteArray()
    private val now = Date()

    private fun verify(
        compact: String,
        anchor: TrustAnchor = pki.anchor,
        content: ByteArray? = manifest,
        at: Date? = now,
        revoked: RevokedSet = RevokedSet.NONE,
        purpose: SignaturePurpose = SignaturePurpose.PLUGIN,
    ) = CertificateSignatures.verify(compact, purpose, anchor, content, at, revoked)

    private fun refused(why: String, block: () -> Unit) {
        try {
            block()
            fail("accepted, but should be refused: $why")
        } catch (expected: IllegalArgumentException) {
            // Refused, as it should be.
        } catch (expected: java.security.GeneralSecurityException) {
            // Refused by the JDK's own certificate or signature check.
        } catch (expected: org.json.JSONException) {
            // Refused as malformed.
        }
    }

    @Test
    fun `a leaf issued by Core verifies and names its origin`() {
        val leaf = pki.leaf()
        val verified = verify(TestPki.jws(manifest, leaf))
        assertTrue(verified.namesOrigin("https://github.com/Droidtop/enginehost-example-plugin"))
        assertFalse(verified.namesOrigin("https://github.com/droidtop/another-plugin"))
        assertEquals(sha256(leaf.keys.public.encoded), verified.leafKeySha256)
        assertTrue(verified.payload.contentEquals(manifest))
    }

    @Test
    fun `an RSA leaf signs RS256`() {
        val leaf = pki.leaf(keys = TestPki.rsa())
        verify(TestPki.jws(manifest, leaf))
        refused("an RSA key under an ES256 header") { verify(TestPki.jws(manifest, leaf, algorithm = "ES256")) }
    }

    @Test
    fun `an EC key under an RS256 header is refused`() {
        refused("alg does not match the key") { verify(TestPki.jws(manifest, pki.leaf(), algorithm = "RS256")) }
    }

    @Test
    fun `one or two intermediates under Core verify, a third does not`() {
        val first = TestPki.issue("CN=Intermediate 1", TestPki.rsa(), pki.core, ca = true, keyUsage = KeyUsage.keyCertSign, eku = null)
        val second = TestPki.issue("CN=Intermediate 2", TestPki.ec(), first, ca = true, keyUsage = KeyUsage.keyCertSign, eku = null)
        val third = TestPki.issue("CN=Intermediate 3", TestPki.ec(), second, ca = true, keyUsage = KeyUsage.keyCertSign, eku = null)
        val underFirst = pki.leaf(issuer = first)
        verify(TestPki.jws(manifest, underFirst, listOf(underFirst, first)))
        val underSecond = pki.leaf(issuer = second)
        verify(TestPki.jws(manifest, underSecond, listOf(underSecond, second, first)))
        val underThird = pki.leaf(issuer = third)
        refused("more than two intermediates") {
            verify(TestPki.jws(manifest, underThird, listOf(underThird, third, second, first)))
        }
    }

    @Test
    fun `an intermediate's path length is honoured`() {
        val first = TestPki.issue(
            "CN=Intermediate 1", TestPki.rsa(), pki.core, ca = true, pathLength = 0, keyUsage = KeyUsage.keyCertSign, eku = null,
        )
        val second = TestPki.issue("CN=Intermediate 2", TestPki.ec(), first, ca = true, keyUsage = KeyUsage.keyCertSign, eku = null)
        val leaf = pki.leaf(issuer = second)
        refused("pathlen 0 with a CA below it") { verify(TestPki.jws(manifest, leaf, listOf(leaf, second, first))) }
    }

    @Test
    fun `the walk stops at Core`() {
        val leaf = pki.leaf()
        refused("x5c carries Core") { verify(TestPki.jws(manifest, leaf, listOf(leaf, pki.core))) }
        refused("x5c carries Core and the root above it") {
            verify(TestPki.jws(manifest, leaf, listOf(leaf, pki.core, pki.ucm)))
        }
        // A signer the owner's wider CA issued directly is not trusted: it chains only to the root above Core.
        val fromRoot = pki.leaf(issuer = pki.ucm)
        refused("chains to the UCM root, not Core") { verify(TestPki.jws(manifest, fromRoot)) }
        refused("chains to the UCM root with the root carried") {
            verify(TestPki.jws(manifest, fromRoot, listOf(fromRoot, pki.ucm)))
        }
    }

    @Test
    fun `Core's own key under another name is still Core, and has no place in the chain`() {
        // Core re-certifying its own key as an "intermediate": it verifies under
        // Core and names Core as issuer, so only the rule that the chain may not
        // carry Core's key refuses it.
        val alias = TestPki.issue(
            "CN=Core alias", pki.core.keys, pki.core, ca = true, keyUsage = KeyUsage.keyCertSign, eku = null,
        )
        val leaf = pki.leaf(issuer = alias)
        refused("an intermediate carrying Core's key") { verify(TestPki.jws(manifest, leaf, listOf(leaf, alias))) }
    }

    @Test
    fun `a certificate whose issuer name is Core's but whose key is not is refused`() {
        val impostor = TestPki.issue(
            "CN=Test Droidtop Core", TestPki.rsa(), ca = true, keyUsage = KeyUsage.keyCertSign, eku = null,
        )
        val leaf = pki.leaf(issuer = impostor)
        refused("issuer name matches, signature does not") { verify(TestPki.jws(manifest, leaf)) }
    }

    @Test
    fun `the purpose is bound by typ and by the leaf's EKU`() {
        val catalogLeaf = pki.leaf(purpose = SignaturePurpose.CATALOG)
        refused("a catalog certificate signing a plugin") { verify(TestPki.jws(manifest, catalogLeaf)) }
        val pluginLeaf = pki.leaf()
        refused("a plugin signature presented as a catalog one") {
            verify(TestPki.jws(manifest, pluginLeaf), purpose = SignaturePurpose.CATALOG)
        }
        // A leaf allowed both purposes: only the header's typ tells them apart.
        val both = TestPki.issue(
            "CN=both", TestPki.ec(), pki.core, eku = listOf(SignaturePurpose.PLUGIN.oid, SignaturePurpose.CATALOG.oid),
        )
        verify(TestPki.jws(manifest, both))
        refused("typ names a plugin, checked as a catalog") {
            verify(TestPki.jws(manifest, both), purpose = SignaturePurpose.CATALOG)
        }
        val noEku = TestPki.issue("CN=no eku", TestPki.ec(), pki.core, eku = null)
        refused("no extended key usage") { verify(TestPki.jws(manifest, noEku)) }
    }

    @Test
    fun `a leaf must be a non-CA digitalSignature key`() {
        val ca = TestPki.issue("CN=ca leaf", TestPki.ec(), pki.core, ca = true, keyUsage = KeyUsage.digitalSignature)
        refused("CA:TRUE leaf") { verify(TestPki.jws(manifest, ca)) }
        val certSign = TestPki.issue("CN=cert sign", TestPki.ec(), pki.core, keyUsage = KeyUsage.digitalSignature or KeyUsage.keyCertSign)
        refused("keyCertSign on the leaf") { verify(TestPki.jws(manifest, certSign)) }
        val noUsage = TestPki.issue("CN=no usage", TestPki.ec(), pki.core, keyUsage = null)
        refused("no keyUsage") { verify(TestPki.jws(manifest, noUsage)) }
        val noSignature = TestPki.issue("CN=encipher", TestPki.ec(), pki.core, keyUsage = KeyUsage.keyAgreement)
        refused("keyUsage without digitalSignature") { verify(TestPki.jws(manifest, noSignature)) }
        // basicConstraints absent is the same as CA:FALSE.
        verify(TestPki.jws(manifest, TestPki.issue("CN=plain", TestPki.ec(), pki.core, ca = null)))
    }

    @Test
    fun `small RSA keys and unknown critical extensions are refused`() {
        val small = pki.leaf(keys = TestPki.rsa(1024))
        refused("1024-bit RSA") { verify(TestPki.jws(manifest, small)) }
        val critical = TestPki.issue("CN=critical", TestPki.ec(), pki.core, extraCritical = "1.2.3.4.5")
        refused("unknown critical extension") { verify(TestPki.jws(manifest, critical)) }
    }

    @Test
    fun `the header refuses crit, and the content is bound`() {
        val leaf = pki.leaf()
        refused("crit present") { verify(TestPki.jws(manifest, leaf, headerExtra = mapOf("crit" to listOf("b64")))) }
        // Unknown parameters are ignored.
        verify(TestPki.jws(manifest, leaf, headerExtra = mapOf("kid" to "anything")))
        val signed = TestPki.jws(manifest, leaf)
        refused("different content") { verify(signed, content = """{"bundleId":"dev.enginehost.other"}""".toByteArray()) }
        refused("detached content but a payload is carried") { verify(TestPki.jws(manifest, leaf, detached = false)) }
        val parts = signed.split('.')
        val flipped = parts[2].toCharArray().also { it[5] = if (it[5] == 'A') 'B' else 'A' }.concatToString()
        refused("altered signature") { verify("${parts[0]}..$flipped") }
        refused("not three parts") { verify("${parts[0]}.${parts[2]}") }
    }

    @Test
    fun `validity is checked at install and catalog time, not at launch`() {
        val expired = TestPki.issue(
            "CN=expired", TestPki.ec(), pki.core, uris = listOf("urn:droidtop:origin:droidtop/enginehost-example-plugin"),
            notBefore = Date(System.currentTimeMillis() - 10_000_000_000), notAfter = Date(System.currentTimeMillis() - 1_000_000),
        )
        val signed = TestPki.jws(manifest, expired)
        refused("expired at install") { verify(signed) }
        verify(signed, at = null)
    }

    @Test
    fun `revocation refuses a certificate, a key, or the anchor anywhere in the chain`() {
        val intermediate = TestPki.issue("CN=Intermediate", TestPki.rsa(), pki.core, ca = true, keyUsage = KeyUsage.keyCertSign, eku = null)
        val leaf = pki.leaf(issuer = intermediate)
        val signed = TestPki.jws(manifest, leaf, listOf(leaf, intermediate))
        verify(signed)
        refused("leaf certificate revoked") { verify(signed, revoked = RevokedSet.of(listOf(sha256(leaf.der).lowercase()), emptyList())) }
        refused("intermediate key revoked") { verify(signed, revoked = RevokedSet.of(emptyList(), listOf(sha256(intermediate.keys.public.encoded)))) }
        refused("Core's key revoked") { verify(signed, revoked = RevokedSet.of(emptyList(), listOf(pki.anchor.keySha256))) }
        // Revoked at launch too: revocation, unlike expiry, stops an installed plugin.
        refused("revoked with no clock") {
            verify(signed, at = null, revoked = RevokedSet.of(listOf(sha256(leaf.der)), emptyList()))
        }
    }

    @Test
    fun `a pinned key anchors a publisher's own certificate or one it issued`() {
        val publisher = TestPki.ec()
        val anchor = TrustAnchor.PinnedKey(publisher.public.encoded)
        val selfSigned = TestPki.issue(
            "CN=Publisher", publisher, uris = listOf("urn:droidtop:origin:someone/their-plugin"),
        )
        verify(TestPki.jws(manifest, selfSigned), anchor = anchor)
        val publisherCa = TestPki.issue("CN=Publisher CA", publisher, ca = true, keyUsage = KeyUsage.keyCertSign, eku = null)
        val issued = TestPki.issue("CN=Publisher signer", TestPki.ec(), publisherCa, uris = listOf("urn:droidtop:origin:someone/their-plugin"))
        verify(TestPki.jws(manifest, issued), anchor = anchor)
        refused("another key's certificate") { verify(TestPki.jws(manifest, pki.leaf()), anchor = anchor) }
        refused("a Core leaf under a pinned key") { verify(TestPki.jws(manifest, pki.leaf()), anchor = TrustAnchor.PinnedKey(TestPki.ec().public.encoded)) }
    }

    @Test
    fun `plugin URNs narrow which bundle IDs a leaf signs`() {
        val any = verify(TestPki.jws(manifest, pki.leaf()))
        assertTrue(any.allowsPlugin("dev.enginehost.anything"))
        val narrowed = verify(
            TestPki.jws(
                manifest,
                pki.leaf(extraUris = listOf("urn:droidtop:plugin:dev.enginehost.godot", "urn:droidtop:plugin:dev.enginehost.rpgmaker.*")),
            ),
        )
        assertTrue(narrowed.allowsPlugin("dev.enginehost.godot"))
        assertTrue(narrowed.allowsPlugin("dev.enginehost.rpgmaker.mz"))
        assertFalse(narrowed.allowsPlugin("dev.enginehost.godotx"))
        assertFalse(narrowed.allowsPlugin("dev.enginehost.rpgmaker"))
        assertFalse(narrowed.allowsPlugin("dev.enginehost.renpy"))
    }

    @Test
    fun `the developer certificate is marked`() {
        val developer = TestPki.issue("CN=Developer", TestPki.ec(), pki.core, uris = listOf("urn:enginehost:developer"))
        val verified = verify(TestPki.jws(manifest, developer))
        assertTrue(verified.isDeveloper)
        assertTrue(verified.origins.isEmpty())
    }

    @Test
    fun `ES256 signatures convert to DER for every value shape`() {
        // Many signatures cover r and s with a high first bit and with leading zero bytes.
        val leaf = pki.leaf()
        repeat(64) { index -> verify(TestPki.jws("$index".toByteArray(), leaf), content = "$index".toByteArray()) }
    }

    @Test
    fun `a revocation list verifies for its catalog only`() {
        val signer = pki.leaf(purpose = SignaturePurpose.REVOCATIONS, extraUris = listOf("urn:droidtop:catalog:enginehost"))
        val revokedKey = sha256(TestPki.ec().public.encoded)
        val list = RevocationList.verify(
            TestPki.revocationList(signer, listOf(signer), "enginehost", 7, keySha256 = listOf(revokedKey.lowercase())),
            pki.anchor, "enginehost", now,
        )
        assertEquals(7, list.sequence)
        assertTrue(list.revoked.revokesKey(revokedKey))
        refused("verified for another catalog") {
            RevocationList.verify(TestPki.revocationList(signer, listOf(signer), "enginehost", 7), pki.anchor, "droidtop", now)
        }
        refused("the payload names another catalog") {
            RevocationList.verify(
                TestPki.revocationList(signer, listOf(signer), "enginehost", 7, listedCatalog = "droidtop"),
                pki.anchor, "enginehost", now,
            )
        }
        val noCatalog = pki.leaf(purpose = SignaturePurpose.REVOCATIONS)
        refused("the signer names no catalog") {
            RevocationList.verify(TestPki.revocationList(noCatalog, listOf(noCatalog), "enginehost", 8), pki.anchor, "enginehost", now)
        }
        refused("a signer the held list revoked") {
            RevocationList.verify(
                TestPki.revocationList(signer, listOf(signer), "enginehost", 8), pki.anchor, "enginehost", now,
                alreadyRevoked = RevokedSet.of(emptyList(), listOf(sha256(signer.keys.public.encoded))),
            )
        }
        val pluginSigner = pki.leaf(extraUris = listOf("urn:droidtop:catalog:enginehost"))
        refused("a plugin-signing certificate signing a revocation list") {
            RevocationList.verify(TestPki.revocationList(pluginSigner, listOf(pluginSigner), "enginehost", 8), pki.anchor, "enginehost", now)
        }
    }
}
